customMethods.script:
draft = system.util.jsonDecode(BlueRidge.Common.Util.convertWrapperObjectToJson(self.view.custom.editDraft)) or {}
cur = draft.get(method) or {}
draft[method] = {"Id": cur.get("Id"), "ItemId": self.view.custom.itemId, "ClosureMethod": method, "Active": False, "PartsPerTray": "", "TraysPerContainer": "", "DunnageCode": "", "CustomerCode": "", "IsSerialized": False, "TargetWeight": "", "ToleranceWeight": ""}
self.view.custom.editDraft = draft
if (self.view.custom.activeField or "").startswith(method + "."):
	self.view.custom.activeField = ""

messageHandlers.script:
af = self.view.custom.activeField or ""
if "." not in af:
	return
method, fld = af.split(".", 1)
a = payload.get("action") if payload else None
# Read and write ONLY the one leaf: a whole-draft rewrite per key lets
# fast presses overwrite each other and scrambles the digits.
block = self.view.custom.editDraft[method]
cur = "%s" % (block[fld] or "")
if a == "key":
	k = "%s" % payload.get("key")
	if k == "." and (fld not in ("TargetWeight", "ToleranceWeight") or "." in cur):
		return
	if len(cur) < 10:
		cur = cur + k
elif a == "backspace":
	cur = cur[:-1]
elif a == "clear":
	cur = ""
else:
	return
block[fld] = cur
